LoadingScreen::LoadingScreen(ScriptSession& session,Renderer& renderer,Text& text,Log& log,IDirect3DTexture9* minimap,bool muted,float gain) : archives_(session.world()->resources().fork()),images_(archives_->root()),renderer_(renderer),assets_(*archives_),screen_(*archives_,images_,renderer,text,"UI\\FrameDef\\Glue\\Loading.fdf","Loading"),backgroundAudio_(*archives_,log,muted,gain),barAudio_(*archives_,log,muted,gain) {
    auto& info=session.world()->data().info;auto local=session.localPlayer().value_or(0);auto race=session.config().players[local].race;std::string name=race==1?"Human":race==2?"Orc":race==3?"Undead":race==4?"NightElf":"Random";auto member=info.loadingModel.empty()?"UI\\Glues\\Loading\\Multiplayer\\Load-Multiplayer-"+name+".mdx":info.loadingModel;if(member.ends_with(".mdl"))member.replace(member.size()-4,4,".mdx");background_=&assets_.model(member,log);bar_=&assets_.model("UI\\Glues\\Loading\\LoadBar\\LoadBar.mdx",log);while(assets_.uploadOne(renderer)){}assets_.ready(renderer);bar_->sequence("Birth");
    bool custom=!info.loadingModel.empty() || !info.loadingTitle.empty();screen_.visible("LoadingCustomPanel",custom);screen_.visible("LoadingMeleePanel",!custom);screen_.setText("LoadingTitleText",info.loadingTitle);screen_.setText("LoadingSubtitleText",info.loadingSubtitle);screen_.setText("LoadingText",info.loadingText);screen_.image("MinimapImage",minimap);screen_.setText("LoadingMeleeMapName",info.name);screen_.setText("LoadingMeleeGameTypeValue",screen_.localized(info.flags&4?"GAMETYPE_MELEE":"GAMETYPE_USE_MAP_SETTINGS"));auto container=screen_.bounds("LoadingMeleePlayerContainer");unsigned row=0;
    for(unsigned id=0;id<16;++id){auto& player=session.config().players[id];if(player.controller==5)continue;auto context="loading-player-"+std::to_string(id);screen_.attach("UI\\FrameDef\\Glue\\Loading.fdf","LoadingPlayerSlot","LoadingMeleePlayerContainer",context);screen_.place(context+"/LoadingPlayerSlot",{container.x,container.y+row*.032f,.256f,.032f});screen_.setText(context+"/LoadingPlayerSlotName",player.name);screen_.visible(context+"/LoadingPlayerSlotLevel",false);screen_.visible(context+"/LoadingPlayerSlotReadyHighlight",false);auto label=player.race==1?"RACE_HUMAN":player.race==2?"RACE_ORC":player.race==3?"RACE_UNDEAD":player.race==4?"RACE_NIGHTELF":"RACE_RANDOM";screen_.setText(context+"/LoadingPlayerSlotRace",screen_.localized(label));++row;}
}
void LoadingScreen::draw(std::uint64_t elapsed,unsigned phase,std::optional<std::pair<size_t,size_t>> uploaded,const std::string& error) {
    auto device=renderer_.device();D3DVIEWPORT9 previous;device->GetViewport(&previous);float scale=std::min(renderer_.width()/.8f,renderer_.height()/.6f);D3DVIEWPORT9 viewport{DWORD((renderer_.width()-.8f*scale)/2),DWORD((renderer_.height()-.6f*scale)/2),DWORD(.8f*scale),DWORD(.6f*scale),0,1};device->SetViewport(&viewport);auto view=sceneMatrix(DirectX::XMMatrixTranslation(0,0,-1)),projection=sceneMatrix(DirectX::XMMatrixOrthographicOffCenterRH(0,.8f,0,.6f,.01f,2)),world=sceneMatrix(DirectX::XMMatrixIdentity());ModelCamera camera{view,{0,0,1},{1,0,0}};background_->draw(elapsed,view,projection,world,true);backgroundAudio_.update(*background_,elapsed,elapsed,world,camera);double progress=uploaded && uploaded->second?double(uploaded->first)/uploaded->second:0;auto barTime=std::uint64_t(progress*double(bar_->sequenceDuration()));bar_->draw(barTime,view,projection,world,true,0xffffffff,nullptr,elapsed);barAudio_.update(*bar_,barTime,elapsed,world,camera);device->SetViewport(&previous);
    const char* stages[]={"准备地图","运行地图初始化","构建地形与水面","载入单位与装饰物","载入游戏界面"};std::string label=uploaded?"上传场景资源 "+std::to_string(uploaded->first)+" / "+std::to_string(uploaded->second):std::string(stages[std::min(phase,4u)])+"…";if(!error.empty())label="载入失败，按 Esc 返回选图。";screen_.setText("LoadingBarText",label);screen_.draw("Loading",{},{});if(!error.empty())screen_.textAt("StandardValueTextTemplate",error,{.02f,.51f,.76f,.045f},true,false,true);
}
